const N = parseInt(process.argv[2], 10) || 0;
const minDepth = 4;
const maxDepth = Math.max(minDepth + 2, N);
const stretchDepth = maxDepth + 1;

class TreeNode {
  constructor(left, right) {
    this.left = left;
    this.right = right;
  }
}

function bottomUpTree(depth) {
  if (depth > 0) {
    return new TreeNode(bottomUpTree(depth - 1), bottomUpTree(depth - 1));
  }
  return new TreeNode(null, null);
}

function itemCheck(node) {
  if (node.left === null) return 1;
  return 1 + itemCheck(node.left) + itemCheck(node.right);
}

const out = [];

{
  const stretchTree = bottomUpTree(stretchDepth);
  out.push("stretch tree of depth " + stretchDepth + "\t check: " + itemCheck(stretchTree));
}

const longLivedTree = bottomUpTree(maxDepth);

for (let depth = minDepth; depth <= maxDepth; depth += 2) {
  const iterations = 1 << (maxDepth - depth + minDepth);
  let check = 0;
  for (let i = 0; i < iterations; i++) {
    const t = bottomUpTree(depth);
    check += itemCheck(t);
  }
  out.push(iterations + "\t trees of depth " + depth + "\t check: " + check);
}

out.push("long lived tree of depth " + maxDepth + "\t check: " + itemCheck(longLivedTree));

process.stdout.write(out.join("\n") + "\n");
