'use strict';
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');
const os = require('os');

function factorials(n) {
  const f = new Array(n + 1);
  f[0] = 1;
  for (let i = 1; i <= n; i++) f[i] = f[i - 1] * i;
  return f;
}

// Process permutations with indices in [idxMin, idxMax)
function runRange(n, idxMin, idxMax, Fact) {
  const p = new Int32Array(n + 1);
  const pp = new Int32Array(n + 1);
  const count = new Int32Array(n + 1);

  // firstPermutation(idxMin)
  for (let i = 0; i < n; i++) p[i] = i;
  let idx = idxMin;
  for (let i = n - 1; i > 0; --i) {
    const d = Math.floor(idx / Fact[i]);
    count[i] = d;
    idx -= d * Fact[i];
    for (let j = 0; j <= i; j++) pp[j] = p[j];
    for (let j = 0; j <= i; j++) p[j] = (j + d <= i) ? pp[j + d] : pp[j + d - i - 1];
  }

  let maxflips = 0, chksum = 0;
  let i = idxMin;
  for (;;) {
    let k = p[0];
    if (k !== 0) {
      for (let j = 0; j < n; j++) pp[j] = p[j];
      let flips = 0;
      do {
        let lo = 0, hi = k;
        while (lo < hi) {
          const t = pp[lo]; pp[lo] = pp[hi]; pp[hi] = t;
          lo++; hi--;
        }
        flips++;
        k = pp[0];
      } while (k !== 0);
      if (flips > maxflips) maxflips = flips;
      chksum += (i % 2 === 0) ? flips : -flips;
    }
    if (++i >= idxMax) break;
    // nextPermutation
    let first = p[1];
    p[1] = p[0];
    p[0] = first;
    let m = 1;
    while (++count[m] > m) {
      count[m++] = 0;
      const next = p[0] = p[1];
      for (let j = 1; j < m; j++) p[j] = p[j + 1];
      p[m] = first;
      first = next;
    }
  }
  return [maxflips, chksum];
}

if (isMainThread) {
  const n = parseInt(process.argv[2], 10);
  const Fact = factorials(n);
  const total = Fact[n];
  let nThreads = 1;
  try {
    nThreads = typeof os.availableParallelism === 'function' ? os.availableParallelism() : os.cpus().length;
  } catch (e) { nThreads = 1; }
  if (!nThreads || nThreads < 1) nThreads = 1;

  const finish = (maxflips, chksum) => {
    process.stdout.write(chksum + '\nPfannkuchen(' + n + ') = ' + maxflips + '\n');
  };

  if (n < 10 || nThreads <= 1) {
    const [mf, cs] = runRange(n, 0, total, Fact);
    finish(mf, cs);
  } else {
    const NCHUNKS = 150;
    const chunk = Math.ceil(total / NCHUNKS);
    const ntasks = Math.ceil(total / chunk);
    const workers = Math.min(nThreads, ntasks);
    const assignments = [];
    for (let w = 0; w < workers; w++) assignments.push([]);
    for (let t = 0; t < ntasks; t++) {
      const lo = t * chunk;
      const hi = Math.min(total, lo + chunk);
      assignments[t % workers].push([lo, hi]);
    }
    let remaining = workers;
    let maxflips = 0, chksum = 0;
    for (let w = 0; w < workers; w++) {
      const worker = new Worker(__filename, { workerData: { n, tasks: assignments[w] } });
      worker.on('message', (msg) => {
        if (msg[0] > maxflips) maxflips = msg[0];
        chksum += msg[1];
        if (--remaining === 0) finish(maxflips, chksum);
      });
      worker.on('error', (err) => { console.error(err); process.exit(1); });
    }
  }
} else {
  const { n, tasks } = workerData;
  const Fact = factorials(n);
  let maxflips = 0, chksum = 0;
  for (const [lo, hi] of tasks) {
    const [mf, cs] = runRange(n, lo, hi, Fact);
    if (mf > maxflips) maxflips = mf;
    chksum += cs;
  }
  parentPort.postMessage([maxflips, chksum]);
}
