'use strict';
const fs = require('fs');

const N = parseInt(process.argv[2], 10);
const IM = 139968, IA = 3877, IC = 29573;
let seed = 42;

const ALU =
  "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" +
  "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" +
  "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" +
  "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" +
  "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";
const ALULEN = ALU.length;
const alu2 = Buffer.from(ALU + ALU, 'ascii');

const BUFSIZE = (1 << 20) + 1024;
const buf = Buffer.allocUnsafe(BUFSIZE);
const FLUSH_AT = BUFSIZE - 128;

function writeAll(b, len) {
  let off = 0;
  while (off < len) {
    try {
      off += fs.writeSync(1, b, off, len - off);
    } catch (e) {
      if (e.code !== 'EAGAIN') throw e;
    }
  }
}

// Precompute symbol for every possible seed value (exact, since r depends only on seed).
function makeTable(symbols, probs) {
  const cum = new Float64Array(probs.length);
  let c = 0;
  for (let i = 0; i < probs.length; i++) { c += probs[i]; cum[i] = c; }
  const t = new Uint8Array(IM);
  let j = 0;
  const last = cum.length - 1;
  for (let s = 0; s < IM; s++) {
    const r = s / IM;
    while (j < last && r >= cum[j]) j++;
    t[s] = symbols.charCodeAt(j);
  }
  return t;
}

const iubTable = makeTable("acgtBDHKMNRSVWY",
  [0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02]);
const homoTable = makeTable("acgt",
  [0.3029549426680, 0.1979883004921, 0.1975473066391, 0.3015094502008]);

function repeatFasta(header, n) {
  let pos = buf.write(header + '\n', 0, 'ascii');
  let k = 0;
  while (n > 0) {
    const L = n < 60 ? n : 60;
    alu2.copy(buf, pos, k, k + L);
    pos += L;
    buf[pos++] = 10;
    k += L;
    if (k >= ALULEN) k -= ALULEN;
    n -= L;
    if (pos > FLUSH_AT) { writeAll(buf, pos); pos = 0; }
  }
  writeAll(buf, pos);
}

function randomFasta(header, table, n) {
  let pos = buf.write(header + '\n', 0, 'ascii');
  let s = seed;
  while (n > 0) {
    const L = n < 60 ? n : 60;
    for (let j = 0; j < L; j++) {
      s = (s * IA + IC) % IM;
      buf[pos++] = table[s];
    }
    buf[pos++] = 10;
    n -= L;
    if (pos > FLUSH_AT) { writeAll(buf, pos); pos = 0; }
  }
  writeAll(buf, pos);
  seed = s;
}

repeatFasta(">ONE Homo sapiens alu", 2 * N);
randomFasta(">TWO IUB ambiguity codes", iubTable, 3 * N);
randomFasta(">THREE Homo sapiens frequency", homoTable, 5 * N);
