'use strict';
const fs = require('fs');

const N = parseInt(process.argv[2], 10) || 0;

// Read all of stdin robustly.
function readStdin() {
  const chunks = [];
  let total = 0;
  const bufSize = 1 << 20;
  let buf = Buffer.allocUnsafe(bufSize);
  for (;;) {
    let n;
    try {
      n = fs.readSync(0, buf, 0, bufSize, null);
    } catch (e) {
      if (e.code === 'EAGAIN') continue;
      if (e.code === 'EOF') break;
      throw e;
    }
    if (n === 0) break;
    chunks.push(buf.subarray(0, n));
    total += n;
    buf = Buffer.allocUnsafe(bufSize);
  }
  return Buffer.concat(chunks, total);
}

const data = readStdin();
const len = data.length;

// Locate ">THREE" header.
let pos = data.indexOf('>THREE');
if (pos < 0) pos = 0;
while (pos < len && data[pos] !== 10) pos++;
pos++;

// Extract sequence as 2-bit codes: (byte >> 1) & 3 -> A=0, C=1, T=2, G=3
const seq = new Uint8Array(len - pos > 0 ? len - pos : 1);
let n = 0;
for (let i = pos; i < len; i++) {
  const b = data[i];
  if (b === 62) break; // '>'
  if (b === 10 || b === 13) continue;
  seq[n++] = (b >> 1) & 3;
}

const LETTERS = 'ACTG';

function encode(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h << 2) | ((s.charCodeAt(i) >> 1) & 3);
  return h >>> 0;
}

const frags = ['GGT', 'GGTA', 'GGTATT', 'GGTATTTTAATT', 'GGTATTTTAATTTATAGT'];
const t3 = encode('GGT');
const t4 = encode('GGTA');
const t6 = encode('GGTATT');
const t12 = encode('GGTATTTTAATT');
const t18tail = encode('GGTATTTTAATTTATAGT'.slice(2)); // last 16 bases
const t18a = (('G'.charCodeAt(0)) >> 1) & 3;
const t18b = (('G'.charCodeAt(0)) >> 1) & 3;

const c1 = new Int32Array(4);
const c2 = new Int32Array(16);
let n3 = 0, n4 = 0, n6 = 0, n12 = 0, n18 = 0;

let h = 0;
for (let i = 0; i < n; i++) {
  const c = seq[i];
  h = (h << 2) | c;
  c1[c]++;
  if (i >= 1) {
    c2[h & 15]++;
    if (i >= 2) {
      if ((h & 63) === t3) n3++;
      if (i >= 3) {
        if ((h & 255) === t4) n4++;
        if (i >= 5) {
          if ((h & 4095) === t6) n6++;
          if (i >= 11) {
            if ((h & 0xFFFFFF) === t12) n12++;
            if (i >= 17 && (h >>> 0) === t18tail &&
                seq[i - 16] === t18b && seq[i - 17] === t18a) {
              n18++;
            }
          }
        }
      }
    }
  }
}

const out = [];

function report(counts, k) {
  const total = n - k + 1;
  const items = [];
  for (let code = 0; code < counts.length; code++) {
    let name = '';
    for (let j = k - 1; j >= 0; j--) name += LETTERS[(code >> (2 * j)) & 3];
    items.push({ name, count: counts[code] });
  }
  items.sort((a, b) => (b.count - a.count) || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  for (const it of items) {
    const pct = total > 0 ? (it.count * 100 / total) : 0;
    out.push(it.name + ' ' + pct.toFixed(3));
  }
  out.push('');
}

report(c1, 1);
report(c2, 2);

out.push(n3 + '\t' + frags[0]);
out.push(n4 + '\t' + frags[1]);
out.push(n6 + '\t' + frags[2]);
out.push(n12 + '\t' + frags[3]);
out.push(n18 + '\t' + frags[4]);

process.stdout.write(out.join('\n') + '\n');
